declare ancien jsonb:='[{"start_year":-221,"start_month":null,"start_day":null,"end_year":null,"end_month":null,"end_day":null,"card_id":"CARD-049-evt-0370","chapter_id":"THM-049","event_id":"EVT-0370","date_text":"221 av. J.-C.","date_precision":"YEAR","date_status":"EXACT","title":"Qin Shi Huang unifie la Chine","body":"Après une longue période de rivalités entre royaumes, le souverain de Qin achève la conquête de ses adversaires et prend le titre de Premier empereur. Qin Shi Huang gouverne les territoires réunis grâce à une administration placée sous son autorité. Il impose des règles communes pour l’écriture, les monnaies et les mesures, et développe les communications. Ces choix facilitent le contrôle d’un vaste empire, mais s’accompagnent d’un pouvoir très contraignant. La dynastie Qin disparaît rapidement ; une partie de son organisation lui survit.","takeaway":"À retenir : Qin Shi Huang réunit des royaumes et met en place des règles communes pour gouverner l’empire.","key_concepts":["unification","empereur","administration"],"sort_order":1,"official_wording":"Repère complémentaire utile au chapitre ; non présenté comme repère officiel obligatoire du BO.","sources":["https://www.metmuseum.org/essays/qin-dynasty-221-206-b-c"]},{"start_year":9,"start_month":null,"start_day":null,"end_year":25,"end_month":null,"end_day":null,"card_id":"CARD-049-evt-0040","chapter_id":"THM-049","event_id":"EVT-0040","date_text":"206 av. J.-C.-220 apr. J.-C., interrompue par le régime de Wang Mang/Xin (9-25 apr. J.-C.)","date_precision":"YEAR_RANGE","date_status":"EXACT","title":"Les Han, une dynastie avec une interruption","body":"La dynastie Han gouverne une grande partie de la Chine après les Qin. Les empereurs s’appuient sur des fonctionnaires pour administrer les territoires, organiser les ressources et faire appliquer leurs décisions. Les échanges avec l’Asie centrale se développent, tandis que les savoirs et les techniques circulent. Ce pouvoir ne se maintient pas sans interruption : Wang Mang prend le trône et fonde les Xin, puis les Han sont rétablis. On distingue donc les Han occidentaux et les Han orientaux, séparés par une période de rupture politique.","takeaway":"À retenir : l’histoire des Han comprend une interruption ; elle ne doit pas être confondue avec le pouvoir de Wang Mang.","key_concepts":["dynastie","fonctionnaire","interruption dynastique"],"sort_order":4,"official_wording":"Dynastie Han","sources":["https://www.metmuseum.org/essays/han-dynasty-206-b-c-220-a-d","https://www.metmuseum.org/toah/ht/05/eac.html"]},{"start_year":-141,"start_month":null,"start_day":null,"end_year":-87,"end_month":null,"end_day":null,"card_id":"CARD-049-han","chapter_id":"THM-049","event_id":"EVT-0041","date_text":"141-87 av. J.-C.","date_precision":"YEAR_RANGE","date_status":"EXACT","title":"La Chine des Han : un autre grand empire","body":"Sous l’empereur Wudi, la dynastie Han gouverne un vaste territoire en Chine. L’empereur s’appuie sur des fonctionnaires pour administrer les régions et prélever des ressources. Les techniques, l’agriculture et les échanges se développent. Des routes relient peu à peu la Chine à l’Asie centrale, même si les marchandises passent souvent par plusieurs intermédiaires. Comparer cet empire à Rome montre que de grandes organisations politiques existent dans différentes parties du monde. Elles possèdent des institutions et des cultures propres.","takeaway":"À retenir : l’empire des Han est une puissance organisée qui participe aux échanges à travers l’Asie.","key_concepts":["empire","fonctionnaire","échange"],"sort_order":2,"official_wording":"Règne de l’empereur Wu/Wudi","sources":["https://www.metmuseum.org/essays/han-dynasty-206-b-c-220-a-d"]},{"start_year":-138,"start_month":null,"start_day":null,"end_year":null,"end_month":null,"end_day":null,"card_id":"CARD-049-evt-0371","chapter_id":"THM-049","event_id":"EVT-0371","date_text":"138 av. J.-C.","date_precision":"YEAR","date_status":"EXACT","title":"Zhang Qian part vers l’Asie centrale","body":"L’empereur Wudi envoie Zhang Qian vers l’ouest pour chercher des alliés contre les Xiongnu, qui menacent les frontières des Han. Le voyage est difficile : l’envoyé est retenu captif avant de pouvoir poursuivre sa route. Il découvre des peuples et des territoires d’Asie centrale et rapporte des informations précieuses. Même si l’alliance souhaitée n’aboutit pas, sa mission élargit les connaissances de la cour chinoise. Elle favorise ensuite des relations diplomatiques et commerciales sur les réseaux que l’on appellera les routes de la soie.","takeaway":"À retenir : une mission diplomatique de Zhang Qian contribue à développer les contacts entre la Chine et l’Asie centrale.","key_concepts":["diplomatie","Asie centrale","routes de la soie"],"sort_order":3,"official_wording":"Repère complémentaire utile au chapitre ; non présenté comme repère officiel obligatoire du BO.","sources":["https://en.wikipedia.org/wiki/Zhang_Qian","https://whc.unesco.org/en/list/1442/"]},{"start_year":220,"start_month":null,"start_day":null,"end_year":null,"end_month":null,"end_day":null,"card_id":"CARD-049-evt-0392","chapter_id":"THM-049","event_id":"EVT-0392","date_text":"220","date_precision":"YEAR","date_status":"EXACT","title":"La fin des Han et la division du pouvoir","body":"À la fin de la dynastie Han, les rivalités de la cour, les révoltes et la puissance des chefs militaires affaiblissent l’empereur. Son autorité réelle se réduit, tandis que plusieurs hommes forts contrôlent des territoires et leurs armées. Le dernier souverain abdique, ce qui marque la fin de la dynastie. La Chine entre ensuite dans une période de division entre royaumes rivaux. Les administrations, les techniques et les traditions développées sous les Han ne disparaissent pas pour autant avec la famille impériale.","takeaway":"À retenir : la fin des Han met fin à une dynastie, mais n’efface pas son héritage politique et culturel.","key_concepts":["dynastie","abdication","division politique"],"sort_order":5,"official_wording":"Repère complémentaire utile au chapitre ; non présenté comme repère officiel obligatoire du BO.","sources":["https://www.metmuseum.org/essays/han-dynasty-206-b-c-220-a-d","https://www.metmuseum.org/toah/ht/05/eac.html"]}]'::jsonb; corrige jsonb:='[{"start_year":-221,"start_month":null,"start_day":null,"end_year":null,"end_month":null,"end_day":null,"card_id":"CARD-049-evt-0370","chapter_id":"THM-049","event_id":"EVT-0370","date_text":"221 av. J.-C.","date_precision":"YEAR","date_status":"EXACT","title":"Qin Shi Huang unifie la Chine","body":"Après une longue période de rivalités entre royaumes, le souverain de Qin achève la conquête de ses adversaires et prend le titre de Premier empereur. Qin Shi Huang gouverne les territoires réunis grâce à une administration placée sous son autorité. Il impose des règles communes pour l’écriture, les monnaies et les mesures, et développe les communications. Ces choix facilitent le contrôle d’un vaste empire, mais s’accompagnent d’un pouvoir très contraignant. La dynastie Qin disparaît rapidement ; une partie de son organisation lui survit.","takeaway":"À retenir : Qin Shi Huang réunit des royaumes et met en place des règles communes pour gouverner l’empire.","key_concepts":["unification","empereur","administration"],"sort_order":1,"official_wording":"Repère complémentaire utile au chapitre ; non présenté comme repère officiel obligatoire du BO.","sources":["https://www.metmuseum.org/essays/qin-dynasty-221-206-b-c"]},{"start_year":-206,"start_month":null,"start_day":null,"end_year":220,"end_month":null,"end_day":null,"card_id":"CARD-049-evt-0040","chapter_id":"THM-049","event_id":"EVT-0040","date_text":"206 av. J.-C.–220 apr. J.-C., avec une interruption entre 9 et 25 apr. J.-C. (interrègne de Wang Mang et transition jusqu’au rétablissement des Han)","date_precision":"YEAR_RANGE","date_status":"CONVENTIONAL","title":"Les Han, une dynastie avec une interruption","body":"La dynastie 