begin
 perform pg_advisory_xact_lock(hashtextextended('histoire.pedagogie',0));
 -- Sur une pile vide, les imports ultérieurs chargent déjà le canon corrigé.
 -- Le scénario local rejoue ce fichier après l’import #92, avant toute activation Han.
 if to_regclass('histoire.pedagogical_units') is null then return; end if;
 if not exists(select 1 from histoire.pedagogical_units where chapter_id='THM-049') then return; end if;
 if (select count(*) from histoire.pedagogical_units where chapter_id=any(array['THM-047','THM-048','THM-049']) and parent_id='THM-006')<>3 then raise exception 'Groupe Han inattendu'; end if;
 if (select array_agg(et.tag_id order by et.tag_id) from histoire.event_tags et join histoire.tags t on t.id=et.tag_id where et.event_id='EVT-0040' and t.tag_type in ('DATE_STATUS','CENTURY')) is distinct from array['TAG-0076','TAG-0085']
  and (select array_agg(et.tag_id order by et.tag_id) from histoire.event_tags et join histoire.tags t on t.id=et.tag_id where et.event_id='EVT-0040' and t.tag_type in ('DATE_STATUS','CENTURY')) is distinct from array['TAG-0074','TAG-0087','TAG-0193'] then raise exception 'Tags temporels Han hors audit';end if;
 select e.title,e.precision,e.date_status,e.playable,e.playable_mode,a.* into strict canon from histoire.events e join histoire.event_answers a on a.event_id=e.id where e.id='EVT-0040';
 if canon.title<>'Dynastie Han' or canon.precision<>'YEAR_RANGE' or not canon.playable or canon.playable_mode<>'RANGE'
  or canon.start_month is not null or canon.start_day is not null or canon.end_month is not null or canon.end_day is not null
  or not((canon.start_year,canon.end_year,canon.date_status,canon.date_text)=(9,25,'EXACT','206 av. J.-C.-220 apr. J.-C., interrompue par le régime de Wang Mang/Xin (9-25 apr. J.-C.)')
    or (canon.start_year,canon.end_year,canon.date_status,canon.date_text)=(-206,220,'CONVENTIONAL','206 av. J.-C.–220 apr. J.-C., avec une interruption entre 9 et 25 apr. J.-C. (interrègne de Wang Mang et transition jusqu’au rétablissement des Han)')) then raise exception 'Canon hors arbitrage : audit requis'; end if;
 actuel:=(select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]'::jsonb) from histoire.chapter_cards t where t.chapter_id='THM-049');
 if actuel is distinct from (select jsonb_agg(x order by x::text) from jsonb_array_elements(ancien)x)
  and actuel is distinct from (select jsonb_agg(x order by x::text) from jsonb_array_elements(corrige)x) then raise exception 'Brouillon Han différent : audit requis'; end if;
 if exists(select 1 from histoire.pedagogical_units where chapter_id='THM-049' and published_fingerprint is not null)
