[]'::jsonb) from histoire.chapter_cards t where t.chapter_id<>'THM-049')::text),'wudi',(select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]'::jsonb) from histoire.event_answers t where t.event_id='EVT-0041'),'evenement_wudi',(select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]'::jsonb) from histoire.events t where t.id='EVT-0041'));
 update histoire.events set date_status='CONVENTIONAL' where id='EVT-0040' and date_status is distinct from 'CONVENTIONAL';
 update histoire.event_tags set tag_id=case tag_id when 'TAG-0076' then 'TAG-0074' when 'TAG-0085' then 'TAG-0193' end
  where event_id='EVT-0040' and tag_id=any(array['TAG-0076','TAG-0085']);
 insert into histoire.event_tags(event_id,tag_id,confidence) values('EVT-0040','TAG-0087','HIGH') on conflict(event_id,tag_id) do nothing;
 update histoire.event_answers set start_year=-206,end_year=220,date_text='206 av. J.-C.–220 apr. J.-C., avec une interruption entre 9 et 25 apr. J.-C. (interrègne de Wang Mang et transition jusqu’au rétablissement des Han)' where event_id='EVT-0040'
  and (start_year,end_year,date_text) is distinct from (-206,220,'206 av. J.-C.–220 apr. J.-C., avec une interruption entre 9 et 25 apr. J.-C. (interrègne de Wang Mang et transition jusqu’au rétablissement des Han)');
 -- Libérer les positions du seul brouillon avant la permutation (contrainte UNIQUE immédiate).
 update histoire.chapter_cards cc set sort_order=cc.sort_order+1000
  from jsonb_populate_recordset(null::histoire.chapter_cards,corrige)c
  where cc.card_id=c.card_id and cc.sort_order<>c.sort_order;
 update histoire.chapter_cards cc set start_year=c.start_year,end_year=c.end_year,date_status=c.date_status,date_text=c.date_text,sort_order=c.sort_order
  from jsonb_populate_recordset(null::histoire.chapter_cards,corrige)c where cc.card_id=c.card_id
  and (cc.start_year,cc.end_year,cc.date_status,cc.date_text,cc.sort_order) is distinct from (c.start_year,c.end_year,c.date_status,c.date_text,c.sort_order);
 if (select count(distinct cc.event_id) from histoire.chapter_cards cc join histoire.events e on e.id=cc.event_id
  where cc.chapter_id='THM-049' and e.playable and e.playable_mode in ('YEAR','MONTH','DAY','RANGE') and cc.start_year is not null)<>5 then raise exception 'Cinq questions admissibles requises'; end if;
 -- Seul le motif historiquement arbitré est retiré ; tout autre blocage reste opérant.
 update histoire.pedagogical_units set blocages=array_remove(blocages,'han-canon-incoherent')
  where chapter_id='THM-049' and 'han-canon-incoherent'=any(blocages);
 if jsonb_build_object('games',md5((select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]'::jsonb) from histoire.games t where true)::text),'game_questions',md5((select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]'::jsonb) from histoire.game_questions t where true)::text),'game_question_editorial_snapshots',md5((select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]'::jsonb) from histoire.game_question_editorial_snapshots t where true)::text),'learning_progress',md5((select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]'::jsonb) from histoire.learning_progress t where true)::text),'learning_progress_editions',md5((select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]'::jsonb) from histoire.learning_progress_editions t where true)::text),'players',md5((select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]'::jsonb) from histoire.players t where true)::text),'kpi_games',md5((select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]'::jsonb) from histoire.kpi_games t where true)::text),'solo_anonymous_limits',md5((select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]'::jsonb) from histoire.solo_anonymous_limits t where true)::text),'pedagogical_card_lineage',md5((select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]'::jsonb) from histoire.pedagogical_card_lineage t where true)::text),'event_chapters',md5((select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]'::jsonb) from histoire.event_chapters t where true)::text),'editions',md5((select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]'::jsonb) from histoire.pedagogical_editions t where t.published)::text),'tags_hors_han',md5((select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]'::jsonb) from histoire.event_tags t where t.event_id<>'EVT-0040')::text),'cartes',md5((select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]'::jsonb) from histoire.chapter_cards t where t.chapter_id<>'THM-049')::text),'wudi',(select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]'::jsonb) from histoire.event_answers t where t.event_id='EVT-0041'),'evenement_wudi',(select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]'::jsonb) from histoire.events t where t.id='EVT-0041')) is distinct from avant then raise exception 'Histoire publiée ou données joueurs modifiées : annulation'; end if;
 if (select coalesce(jsonb_agg(to_jsonb(t) order by to_jsonb(t)::text),'[]'::jsonb) from histoire.chapter_cards t where t.chapter_id='THM-049') is distinct from (select jsonb_agg(x order by x::text) from jsonb_array_elements(corrige)x) then raise exception 'Correction incomplète'; end if;
end $han117$;
